      out.write("      <data:navMessage/>\r\n");
      out.write("    </div>\r\n");
      out.write("    <div class='status-msg-border'>\r\n");
      out.write("      <div class='status-msg-bg'>\r\n");
      out.write("        <div class='status-msg-hidden'><data:navMessage/></div>\r\n");
      out.write("      </div>\r\n");
      out.write("    </div>\r\n");
      out.write("  </div>\r\n");
