      out.write("  </b:if>\r\n");
      out.write("</b:includable>\r\n");
      out.write("  <b:includable id='threaded-comment-form' var='post'>\r\n");
      out.write("  <div class='comment-form'>\r\n");
      out.write("    <a name='comment-form'/>\r\n");
      out.write("    <b:if cond='data:mobile'>\r\n");
      out.write("      <p><data:blogCommentMessage/></p>\r\n");
      out.write("      <data:blogTeamBlogMessage/>\r\n");
      out.write("      <a expr:href='data:post.commentFormIframeSrc' id='comment-editor-src'/>\r\n");
      out.write("      <iframe allowtransparency='true' class='blogger-iframe-colorize blogger-comment-from-post' frameborder='0' height='410' id='comment-editor' name='comment-editor' src='' style='display: none' width='100%'/>\r\n");
      out.write("    <b:else/>\r\n");
      out.write("      <p><data:blogCommentMessage/></p>\r\n");
      out.write("      <data:blogTeamBlogMessage/>\r\n");
      out.write("      <a expr:href='data:post.commentFormIframeSrc' id='comment-editor-src'/>\r\n");
      out.write("      <iframe allowtransparency='true' class='blogger-iframe-colorize blogger-comment-from-post' frameborder='0' height='410' id='comment-editor' name='comment-editor' src='' width='100%'/>\r\n");
      out.write("    </b:if>\r\n");
      out.write("    <data:post.friendConnectJs/>\r\n");
      out.write("    <data:post.cmtfpIframe/>\r\n");
      out.write("    <script type='text/javascript'>\r\n");
      out.write("      BLOG_CMT_createIframe(&#39;<data:post.appRpcRelayPath/>&#39;, &#39;<data:post.communityId/>&#39;);\r\n");
      out.write("    </script>\r\n");
      out.write("  </div>\r\n");
      out.write("</b:includable>\r\n");
      out.write("  <b:includable id='threaded_comment_js' var='post'>\r\n");
      out.write("  <script async='async' expr:src='data:post.commentSrc' type='text/javascript'/>\r\n");
      out.write("\r\n");
      out.write("  <script type='text/javascript'>\r\n");
      out.write("    (function() {\r\n");
      out.write("      var items = <data:post.commentJso/>;\r\n");
      out.write("      var msgs = <data:post.commentMsgs/>;\r\n");
      out.write("      var config = <data:post.commentConfig/>;\r\n");
      out.write("\r\n");
      out.write("// <![CDATA[\r\n");
      out.write("      var cursor = null;\r\n");
      out.write("      if (items && items.length > 0) {\r\n");
      out.write("        cursor = parseInt(items[items.length - 1].timestamp) + 1;\r\n");
      out.write("      }\r\n");
      out.write("\r\n");
      out.write("      var bodyFromEntry = function(entry) {\r\n");
      out.write("        if (entry.gd$extendedProperty) {\r\n");
      out.write("          for (var k in entry.gd$extendedProperty) {\r\n");
      out.write("            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {\r\n");
      out.write("              return '<span class=\"deleted-comment\">' + entry.content.$t + '</span>';\r\n");
      out.write("            }\r\n");
      out.write("          }\r\n");
      out.write("        }\r\n");
      out.write("        return entry.content.$t;\r\n");
      out.write("      }\r\n");
      out.write("\r\n");
      out.write("      var parse = function(data) {\r\n");
      out.write("        cursor = null;\r\n");
      out.write("        var comments = [];\r\n");
      out.write("        if (data && data.feed && data.feed.entry) {\r\n");
      out.write("          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {\r\n");
      out.write("            var comment = {};\r\n");
      out.write("            // comment ID, parsed out of the original id format\r\n");
      out.write("            var id = /blog-(\\d+).post-(\\d+)/.exec(entry.id.$t);\r\n");
      out.write("            comment.id = id ? id[2] : null;\r\n");
      out.write("            comment.body = bodyFromEntry(entry);\r\n");
      out.write("            comment.timestamp = Date.parse(entry.published.$t) + '';\r\n");
      out.write("            if (entry.author && entry.author.constructor === Array) {\r\n");
      out.write("              var auth = entry.author[0];\r\n");
      out.write("              if (auth) {\r\n");
      out.write("                comment.author = {\r\n");
      out.write("                  name: (auth.name ? auth.name.$t : undefined),\r\n");
      out.write("                  profileUrl: (auth.uri ? auth.uri.$t : undefined),\r\n");
      out.write("                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)\r\n");
      out.write("                };\r\n");
      out.write("              }\r\n");
      out.write("            }\r\n");
      out.write("            if (entry.link) {\r\n");
      out.write("              if (entry.link[2]) {\r\n");
      out.write("                comment.link = comment.permalink = entry.link[2].href;\r\n");
      out.write("              }\r\n");
      out.write("              if (entry.link[3]) {\r\n");
      out.write("                var pid = /.*comments\\/default\\/(\\d+)\\?.*/.exec(entry.link[3].href);\r\n");
      out.write("                if (pid && pid[1]) {\r\n");
      out.write("                  comment.parentId = pid[1];\r\n");
      out.write("                }\r\n");
      out.write("              }\r\n");
      out.write("            }\r\n");
      out.write("            comment.deleteclass = 'item-control blog-admin';\r\n");
      out.write("            if (entry.gd$extendedProperty) {\r\n");
      out.write("              for (var k in entry.gd$extendedProperty) {\r\n");
      out.write("                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {\r\n");
      out.write("                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;\r\n");
      out.write("                }\r\n");
      out.write("              }\r\n");
      out.write("            }\r\n");
      out.write("            comments.push(comment);\r\n");
      out.write("          }\r\n");
      out.write("        }\r\n");
      out.write("        return comments;\r\n");
      out.write("      };\r\n");
      out.write("\r\n");
      out.write("      var paginator = function(callback) {\r\n");
      out.write("        if (hasMore()) {\r\n");
      out.write("          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';\r\n");
      out.write("          if (cursor) {\r\n");
      out.write("            url += '&published-min=' + new Date(cursor).toISOString();\r\n");
      out.write("          }\r\n");
      out.write("          window.bloggercomments = function(data) {\r\n");
      out.write("            var parsed = parse(data);\r\n");
      out.write("            cursor = parsed.length < 50 ? null\r\n");
      out.write("                : parseInt(parsed[parsed.length - 1].timestamp) + 1\r\n");
      out.write("            callback(parsed);\r\n");
      out.write("            window.bloggercomments = null;\r\n");
      out.write("          }\r\n");
      out.write("          url += '&callback=bloggercomments';\r\n");
      out.write("          var script = document.createElement('script');\r\n");
      out.write("          script.type = 'text/javascript';\r\n");
      out.write("          script.src = url;\r\n");
      out.write("          document.getElementsByTagName('head')[0].appendChild(script);\r\n");
      out.write("        }\r\n");
      out.write("      };\r\n");
      out.write("      var hasMore = function() {\r\n");
      out.write("        return !!cursor;\r\n");
      out.write("      };\r\n");
      out.write("      var getMeta = function(key, comment) {\r\n");
      out.write("        if ('iswriter' == key) {\r\n");
      out.write("          var matches = !!comment.author\r\n");
      out.write("              && comment.author.name == config.authorName\r\n");
      out.write("              && comment.author.profileUrl == config.authorUrl;\r\n");
      out.write("          return matches ? 'true' : '';\r\n");
      out.write("        } else if ('deletelink' == key) {\r\n");
      out.write("          return config.baseUri + '/delete-comment.g?blogID='\r\n");
      out.write("               + config.blogId + '&postID=' + comment.id;\r\n");
      out.write("        } else if ('deleteclass' == key) {\r\n");
      out.write("          return comment.deleteclass;\r\n");
      out.write("        }\r\n");
      out.write("        return '';\r\n");
      out.write("      };\r\n");
      out.write("\r\n");
      out.write("      var replybox = null;\r\n");
      out.write("      var replyUrlParts = null;\r\n");
      out.write("      var replyParent = undefined;\r\n");
      out.write("\r\n");
      out.write("      var onReply = function(commentId, domId) {\r\n");
      out.write("        if (replybox == null) {\r\n");
      out.write("          // lazily cache replybox, and adjust to suit this style:\r\n");
      out.write("          replybox = document.getElementById('comment-editor');\r\n");
      out.write("          if (replybox != null) {\r\n");
      out.write("            replybox.height = '250px';\r\n");
      out.write("            replybox.style.display = 'block';\r\n");
      out.write("            replyUrlParts = replybox.src.split('#');\r\n");
      out.write("          }\r\n");
      out.write("        }\r\n");
      out.write("        if (replybox && (commentId !== replyParent)) {\r\n");
      out.write("          document.getElementById(domId).insertBefore(replybox, null);\r\n");
      out.write("          replybox.src = replyUrlParts[0]\r\n");
      out.write("              + (commentId ? '&parentID=' + commentId : '')\r\n");
      out.write("              + '#' + replyUrlParts[1];\r\n");
      out.write("          replyParent = commentId;\r\n");
      out.write("        }\r\n");
      out.write("      };\r\n");
      out.write("\r\n");
      out.write("      var hash = (window.location.hash || '#').substring(1);\r\n");
      out.write("      var startThread, targetComment;\r\n");
      out.write("      if (/^comment-form_/.test(hash)) {\r\n");
      out.write("        startThread = hash.substring('comment-form_'.length);\r\n");
      out.write("      } else if (/^c[0-9]+$/.test(hash)) {\r\n");
      out.write("        targetComment = hash.substring(1);\r\n");
      out.write("      }\r\n");
      out.write("\r\n");
      out.write("      // Configure commenting API:\r\n");
      out.write("      var configJso = {\r\n");
      out.write("        'maxDepth': config.maxThreadDepth\r\n");
      out.write("      };\r\n");
      out.write("      var provider = {\r\n");
      out.write("        'id': config.postId,\r\n");
      out.write("        'data': items,\r\n");
      out.write("        'loadNext': paginator,\r\n");
      out.write("        'hasMore': hasMore,\r\n");
      out.write("        'getMeta': getMeta,\r\n");
      out.write("        'onReply': onReply,\r\n");
      out.write("        'rendered': true,\r\n");
      out.write("        'initComment': targetComment,\r\n");
      out.write("        'initReplyThread': startThread,\r\n");
      out.write("        'config': configJso,\r\n");
      out.write("        'messages': msgs\r\n");
      out.write("      };\r\n");
      out.write("\r\n");
      out.write("      var render = function() {\r\n");
      out.write("        if (window.goog && window.goog.comments) {\r\n");
      out.write("          var holder = document.getElementById('comment-holder');\r\n");
      out.write("          window.goog.comments.render(holder, provider);\r\n");
      out.write("        }\r\n");
      out.write("      };\r\n");
      out.write("\r\n");
      out.write("      // render now, or queue to render when library loads:\r\n");
      out.write("      if (window.goog && window.goog.comments) {\r\n");
      out.write("        render();\r\n");
      out.write("      } else {\r\n");
      out.write("        window.goog = window.goog || {};\r\n");
      out.write("        window.goog.comments = window.goog.comments || {};\r\n");
      out.write("        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];\r\n");
      out.write("        window.goog.comments.loadQueue.push(render);\r\n");
      out.write("      }\r\n");
      out.write("    })();\r\n");
      out.write("// ]]>\r\n");
      out.write("  </script>\r\n");
      out.write("</b:includable>\r\n");
      out.write("  <b:includable id='threaded_comments' var='post'>\r\n");
      out.write("			<div class='post-comments' id='comments'>\r\n");
      out.write("\r\n");
      out.write("				<div class='post-box'>\r\n");
      out.write("					<h4 class='post-box-title'> \r\n");
      out.write("						<b:if cond='data:post.numComments == 1'>\r\n");
      out.write("							1 <data:commentLabel/>\r\n");
      out.write("						<b:else/>\r\n");
      out.write("							<data:post.numComments/> <data:commentLabelPlural/>\r\n");
      out.write("						</b:if>\r\n");
      out.write("					</h4>\r\n");
      out.write("				</div>\r\n");
      out.write("				<div class='comments'>		\r\n");
      out.write("					<b:if cond='data:post.embedCommentForm'>\r\n");
      out.write("						<b:include data='post' name='threaded_comment_js'/>\r\n");
      out.write("					</b:if>\r\n");
      out.write("					<div id='comment-holder'>\r\n");
      out.write("						<data:post.commentHtml/>\r\n");
      out.write("					</div>\r\n");
      out.write("				</div>\r\n");
      out.write("				\r\n");
      out.write("				<p class='comment-footer'>\r\n");
      out.write("					<b:if cond='data:post.allowNewComments'>\r\n");
      out.write("						<b:include data='post' name='threaded-comment-form'/>\r\n");
