      out.write("				</p>\r\n");
      out.write("\r\n");
      out.write("				<b:if cond='data:showCmtPopup'>\r\n");
      out.write("					<div id='comment-popup'>	\r\n");
      out.write("						<iframe allowtransparency='true' frameborder='0' id='comment-actions' name='comment-actions' scrolling='no'>\r\n");
      out.write("						</iframe>\r\n");
      out.write("					</div>\r\n");
      out.write("				</b:if>\r\n");
      out.write("\r\n");
      out.write("				<div id='backlinks-container'>\r\n");
      out.write("					<div expr:id='data:widget.instanceId + &quot;_backlinks-container&quot;'>\r\n");
      out.write("						<b:if cond='data:post.showBacklinks'>\r\n");
      out.write("							<b:include data='post' name='backlinks'/>\r\n");
      out.write("						</b:if>\r\n");
      out.write("					</div>\r\n");
      out.write("				</div>\r\n");
      out.write("			</div>						\r\n");
      out.write("		\r\n");
      out.write("\r\n");
      out.write("		</b:includable>\r\n");
      out.write("</b:widget>\r\n");
      out.write("</b:section>\r\n");
      out.write("		\r\n");
      out.write("		<b:section id='sidebar' showaddelement='yes'>\r\n");
      out.write("<b:widget id='Text1' locked='false' title='About me' type='Text'>\r\n");
      out.write("  <b:widget-settings>\r\n");
      out.write("    <b:widget-setting name='content'><![CDATA[<center>					<div class=\"photo-profile\"><br /><br/><br/><img alt=\"a\" class=\"image wp-image-139  attachment-medium size-medium\" height=\"300\" sizes=\"(max-width: 300px) 100vw, 300px\" src=\"https://1.bp.blogspot.com/-iY6mm1MEMvk/XVb64uLtepI/AAAAAAAAKoA/DAQ8lE5JWS0tv7ER0S0Gw8uxArGRvkGWwCLcBGAs/s1600/11351973_1011494582204741_51803517_n.jpg\" / /><br />									</div>								<br />	<br /><h2>Sarah Nelson</h2><p>We are the Backpack Traveler, your favorite travel assistants!</p></center>]]></b:widget-setting>\r\n");
